I found that parsing this contract ends in a stack overflow.
```solidity
pragma solidity ^0.8.7;

contract TestContract {
    struct Data {
        bytes32 a1;
        bytes32 a2;
    }

    mapping(uint176 => bytes32) Hashes;

    constructor() {}

    function getdata(uint176 id, bool needHash) public view returns (Data memory g) {
        (g.a1, g.a2) = (Hashes[id+1], Hashes[id+2]);
    }
}
```

this seems to be when its casting the `StorageRef(false, Bytes(32))` to  `Ref(Bytes(32))`

```js
from cast: StorageRef(false, Bytes(32))
to cast: Ref(Bytes(32))
from cast: Ref(StorageRef(false, Bytes(32)))
to cast: Ref(Bytes(32))
```
based on the result that I was getting with some debug prints in the function `cast` I noticed that the function checks if the `to` needs a `Ref`, and try creates a `Ref` from the `from`.  this cause an infinite loop.

https://github.com/hyperledger-labs/solang/blob/5da5377b6fce0d1aec98fa58041a4126540a226d/src/sema/expression.rs#L540-L550

one solution that seems to be working is not dereference when the `to` object type is a `Type::StorageRef`, but as I don't have experience with this codebase I didn't create a pull request.

```solidity
      contract Testing {

    struct PaddedStruct {
        uint128 a;
        uint8 b;
        bytes32 c;
    }

    PaddedStruct[2][3][] stor_arr;

    function addData() public {
        PaddedStruct memory a = PaddedStruct(56, 1, "oi");
        PaddedStruct memory b = PaddedStruct(78, 6, "bc");
        PaddedStruct memory c = PaddedStruct(89, 4, "sn");
        PaddedStruct memory d = PaddedStruct(42, 56, "cn");
        PaddedStruct memory e = PaddedStruct(23, 78, "fr");
        PaddedStruct memory f = PaddedStruct(445, 46, "br");

        PaddedStruct[2][3] memory vec = [[a, b], [c, d], [e, f]];
        stor_arr.push(vec);
    }

    function getThis() public view returns (uint32) {
        PaddedStruct[2][3][] memory arr2 = stor_arr;

        return arr2.length;
    }
}
  
```
Calling `getThis` after `addData` returns 6, instead it should return 1. If we modify `stor_arr` to `PaddedStruct[2][2][] stor_arr` and do all the necessary changes, `addData` returns 4. I think we are incorrectly merging the first two dimensions into one.
